"""Leaf 1.6: the Resources page (generated by tools/resources_page.py) and the account form (registration, legacy BuddyPress)."""
import json, os, re, subprocess
from . import CONTRAST, SMALL_TARGETS, SMALL_TEXT, WRONG_FONT, UNDER_BARS

ROOT = os.path.dirname(os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
BOTTOM = "scrollTo({top: document.documentElement.scrollHeight, behavior: 'instant'})"   # the site scrolls smoothly; jump instead

ROWS = r"""() => [...document.querySelectorAll('.acx-res')].map(li => {
  const r = e => e.getBoundingClientRect(), th = li.querySelector('.acx-res-thumb'), head = li.querySelector('.acx-title');
  const t = li.querySelector('.acx-title a'), lefts = [...t.getClientRects()].map(x => Math.round(x.left));
  const open = li.querySelector('.acx-act .acx-btn'), dl = li.querySelector('.acx-res-dl'), doi = li.querySelector('.acx-res-src a');
  return { float: getComputedStyle(th).float, thumbRight: Math.round(r(th).right), thumbW: Math.round(r(th).width), headLeft: Math.round(r(head).left),
    sameRow: r(head).top < r(th).bottom, titleLefts: [...new Set(lefts)],
    open: [open.getAttribute('href'), Math.round(r(open).height), Math.round(r(open).width)],
    dl: [dl.getAttribute('href'), dl.hasAttribute('download'), Math.round(r(dl).height), Math.round(r(dl).width), dl.textContent.trim()],
    doi: doi ? [doi.getAttribute('href'), Math.round(r(doi).height)] : null };
})"""

CONTRAST_OF = r"""(sel) => { const e = document.querySelector(sel), cs = getComputedStyle(e);
  const rgb = c => c.match(/[\d.]+/g).slice(0, 3).map(Number), lum = m => { const f = v => { v /= 255; return v <= .03928 ? v / 12.92 : Math.pow((v + .055) / 1.055, 2.4) };
    return .2126 * f(m[0]) + .7152 * f(m[1]) + .0722 * f(m[2]) };
  const a = lum(rgb(cs.color)), b = lum(rgb(cs.backgroundColor));
  return +((Math.max(a, b) + .05) / (Math.min(a, b) + .05)).toFixed(2) }"""


def no_sideways(ctx, path, tag):
    for w, h in ((390, 844), (320, 640)):
        pg = ctx.b.new_context(viewport={"width": w, "height": h}, device_scale_factor=2, is_mobile=True, has_touch=True).new_page()
        pg.goto(ctx.BASE + path, wait_until="load"); pg.wait_for_timeout(300)
        sw = pg.evaluate("document.documentElement.scrollWidth")
        wide = pg.evaluate(f"[...document.querySelectorAll('#main *')].filter(e => e.getClientRects().length && e.getBoundingClientRect().right > {w} + 0.5).map(e => e.tagName + '.' + e.className).slice(0, 4)")
        ctx.check(sw == w and not wide, f"{tag} @{w}: no sideways scroll ({sw}px) and nothing past the right edge {wide or ''}")
        pg.context.close()


def fn_res(ctx):
    check = ctx.check
    print("\n== Resources on phones ==")
    items = json.load(open(os.path.join(ROOT, "tools", "resources.json"), encoding="utf-8"))["items"]
    pg = ctx.phone(ctx.PAGES["resources"])
    rows = pg.evaluate(ROWS)
    check(len(rows) == len(items) > 0, f"rows: {len(rows)} on the page, {len(items)} in resources.json")
    for r, it in zip(rows, items):
        name = it["file"][:-4][:28]
        check(r["float"] == "none" and r["sameRow"] and r["thumbW"] == 64 and r["headLeft"] >= r["thumbRight"] + 8,
              f"{name}: first page (64px) beside kind and title, no float {r['float'], r['thumbW'], r['thumbRight'], r['headLeft']}")
        check(len(r["titleLefts"]) == 1, f"{name}: every title line starts at the same left edge {r['titleLefts']}")
        pdf = "files/" + it["file"]
        check(r["open"][0] == pdf and r["open"][1] >= 44 and r["open"][2] >= 44, f"{name}: Open PDF is {r['open'][1]}px tall and opens {r['open'][0]}")
        check(r["dl"][0] == pdf and r["dl"][1] and r["dl"][2] >= 44 and re.search(r"\d (KB|MB)$", r["dl"][4]),
              f"{name}: Download is {r['dl'][2]}px tall, downloads {r['dl'][0]}, shows the size ({r['dl'][4]})")
        if it.get("doi"):
            check(r["doi"] and r["doi"][0] == "https://doi.org/" + it["doi"] and r["doi"][1] >= 44, f"{name}: DOI row {r['doi']}")
        else:
            check(r["doi"] is None, f"{name}: no DOI row when there is no DOI")
    acts = pg.evaluate("[...document.querySelectorAll('.acx-res .acx-act')].map(a => [...a.children].map(c => Math.round(c.getBoundingClientRect().top)))")
    check(all(len(set(a)) == 1 for a in acts), f"actions: Open PDF and Download share one row {acts}")
    filled = pg.evaluate("[getComputedStyle(document.querySelector('.acx-res .acx-btn')).backgroundColor, getComputedStyle(document.querySelector('.acx-res-dl')).backgroundColor]")
    check(filled == ["rgb(14, 122, 131)", "rgb(232, 246, 247)"], f"actions: Open PDF filled teal, Download tinted {filled}")
    edges = pg.evaluate("[...document.querySelectorAll('.acx-res-list, .acx-res-lead, .entry-title')].map(e => [Math.round(e.getBoundingClientRect().left), Math.round(390 - e.getBoundingClientRect().right)])")
    check(all(e == [16, 16] for e in edges), f"16px gutter on both sides {edges}")
    groups = pg.evaluate("[...document.querySelectorAll('.acx-res-list')].map(l => [getComputedStyle(l).backgroundColor, getComputedStyle(l).borderRadius])")
    check(all(g == ["rgb(255, 255, 255)", "12px"] for g in groups) and pg.evaluate("getComputedStyle(document.body).backgroundColor") == "rgb(246, 248, 250)",
          f"groups: white 12px inset lists on the grey ground {groups}")
    small = pg.evaluate(SMALL_TARGETS, ".acx-res-root *")
    check(not small, f"targets at least 44px {small[:4]}")
    tiny = pg.evaluate(SMALL_TEXT, ".acx-res-root *, .acx-page-res .entry-title")
    check(not tiny, f"text at least 13px {tiny[:4]}")
    font = pg.evaluate(WRONG_FONT, ".acx-res-root *, .acx-page-res .entry-title")
    check(not font, f"all text in Inter {font[:4]}")
    low = pg.evaluate(CONTRAST, ".acx-res-root *, .acx-page-res .entry-title")
    check(not low, f"contrast {low[:3]}")
    under = pg.evaluate(UNDER_BARS, ".acx-res-group > .acx-h2")
    check(not under, f"group headers land below the top bar {under}")
    pg.evaluate(BOTTOM); pg.wait_for_timeout(200)
    clear = pg.evaluate("[...document.querySelectorAll('.acx-res-more, .acx-footer')].map(e => e.getBoundingClientRect().bottom <= document.querySelector('.acx-m-tabs').getBoundingClientRect().top + 0.5)")
    check(clear == [True, True], f"the contact line and the footer clear the tab bar at the bottom {clear}")
    pg.context.close()
    no_sideways(ctx, ctx.PAGES["resources"], "resources")


FIELD = re.compile(r'<(input|select|textarea)\b([^>]*)>')
ATTR = lambda a, k: (re.search(rf'\b{k}="([^"]*)"', a) or [None, None])[1]


def legacy_form():
    h = subprocess.run(["git", "-C", ROOT, "show", "HEAD:registration/index.html"], capture_output=True, text=True, check=True).stdout
    a = h.find('id="signup-form"'); s = h.rfind("<form", 0, a); e = h.find("</form>", a)
    assert a > 0 and s > 0 and e > a, "signup form not found in the committed registration page"
    tag = h[s:h.find(">", s) + 1]
    fields = [[ATTR(m.group(2), "name"), ATTR(m.group(2), "type") or m.group(1)] for m in FIELD.finditer(h[s:e])]
    return ATTR(tag, "action"), ATTR(tag, "method"), fields


def fn_reg(ctx):
    check = ctx.check
    print("\n== Registration form on phones ==")
    pg = ctx.phone(ctx.PAGES["registration"])
    check(not pg.is_visible(".login-split") and not pg.is_visible(".register-section-logo"), "the cropped banner and the repeated logo are hidden")
    action, method, fields = legacy_form()
    live = pg.evaluate("""(() => { const f = document.getElementById('signup-form');
        return [f.getAttribute('action'), f.getAttribute('method'), [...f.querySelectorAll('input, select, textarea')].map(e => [e.getAttribute('name'), e.getAttribute('type') || e.tagName.toLowerCase()])] })()""")
    check(live[0] == action and live[1] == method and live[2] == fields and len(fields) >= 8,
          f"form action {live[0]!r}, method and {len(live[2])} field names match the committed markup")
    boxes = pg.evaluate("""[...document.querySelectorAll('#signup-form input, #signup-form select')].filter(e => e.getClientRects().length && e.type !== 'submit')
        .map(e => [e.name, parseFloat(getComputedStyle(e).fontSize), Math.round(e.getBoundingClientRect().height)])""")
    check(len(boxes) == 7 and all(fs >= 16 and h >= 48 for _, fs, h in boxes), f"every field has 16px+ text and is 48px+ tall {boxes}")
    sub = pg.evaluate("(r => [Math.round(r.height), Math.round(r.width)])(document.getElementById('signup_submit').getBoundingClientRect())")
    ratio = pg.evaluate(CONTRAST_OF, "#signup_submit")
    check(sub[0] >= 50 and sub[1] == 358 and ratio >= 4.5, f"Create Account is full width and {sub[0]}px tall, contrast {ratio}:1")
    head = pg.evaluate("""(() => { const h = document.querySelector('.entry-header .entry-title'), cs = getComputedStyle(h), r = h.getBoundingClientRect();
        return [cs.fontSize, cs.fontWeight, Math.round(r.left)] })()""")
    check(head == ["28px", "700", 16], f"title 28px bold at the 16px gutter {head}")
    edges = pg.evaluate("(r => [Math.round(r.left), Math.round(390 - r.right)])(document.getElementById('signup_email').getBoundingClientRect())")
    check(edges == [16, 16], f"fields sit on the 16px gutter {edges}")
    # hidden inputs (field ids, nonce, referer) and the closed Terms dialog have no box, so the helpers skip them
    small = pg.evaluate(SMALL_TARGETS, "#main *")
    check(not small, f"targets at least 44px, including sign in, show password and Terms {small[:4]}")
    tiny = pg.evaluate(SMALL_TEXT, "#main *")
    check(not tiny, f"text at least 13px {tiny[:4]}")
    font = pg.evaluate(WRONG_FONT, "#main *")
    check(not font, f"all text in Inter {font[:4]}")
    low = pg.evaluate(CONTRAST, "#main *")
    check(not low, f"contrast, helper text included {low[:3]}")
    pg.focus("#signup_email")
    ring = pg.evaluate("(cs => [cs.borderTopColor, cs.boxShadow.slice(0, 22)])(getComputedStyle(document.getElementById('signup_email')))")
    check(ring[0] == "rgb(14, 122, 131)" and ring[1] != "none", f"focus: teal border and ring {ring}")
    pg.evaluate(BOTTOM); pg.wait_for_timeout(200)
    clear = pg.evaluate("document.getElementById('signup_submit').getBoundingClientRect().bottom <= document.querySelector('.acx-m-tabs').getBoundingClientRect().top")
    check(clear, "the submit button clears the tab bar at the bottom")
    pg.context.close()
    no_sideways(ctx, ctx.PAGES["registration"], "registration")


SECTIONS = {"resources": fn_res, "registration": fn_reg}
